<?php
session_start();require '../includes/db_connect.php';require_once '../includes/privacy_lifecycle.php';
if(!isset($_SESSION['logged_in'])){header('Location: ../admin_login.php');exit;}$role=$_SESSION['role'];$actor=(int)$_SESSION['user_id'];$action=$_POST['action']??'';
$studentBack='../student/privacy_requests.php';$adminBack='../super_admin/privacy_lifecycle.php';
try{
 if($action==='submit_request'){
  if($role!=='Student')throw new RuntimeException('Only data subjects may submit this request.');$type=$_POST['request_type']??'';$allowed=['Access','Correction','Anonymization','Erasure or Blocking','Consent Withdrawal'];$details=trim($_POST['details']??'');if(!in_array($type,$allowed,true)||mb_strlen($details)<10)throw new RuntimeException('Select a valid request and provide at least 10 characters of details.');
  $pdo->prepare('INSERT INTO privacy_requests(UserID,RequestType,RequestDetails,DueAt) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 30 DAY))')->execute([$actor,$type,$details]);logAudit($pdo,$actor,'Privacy Request Submitted',"$type request #{$pdo->lastInsertId()} submitted.");$_SESSION['success']='Your privacy request was submitted. The target response date is within 30 days.';header('Location: '.$studentBack);exit;
 }
 if($role!=='Super_Admin')throw new RuntimeException('Only the authorized Super Administrator may manage privacy lifecycle records.');
 if($action==='save_policy'){
  $id=(int)$_POST['policy_id'];$days=(int)$_POST['retention_days'];$method=$_POST['disposal_method']??'';$basis=trim($_POST['legal_basis']??'');$trigger=trim($_POST['trigger_event']??'');if($days<1||$days>36500||!in_array($method,['Anonymize','Secure Delete','Review Only'],true)||mb_strlen($basis)<10||mb_strlen($trigger)<5)throw new RuntimeException('Retention period, trigger, method, or legal basis is invalid.');$pdo->prepare('UPDATE privacy_retention_policies SET RetentionDays=?,TriggerEvent=?,DisposalMethod=?,LegalBasis=?,UpdatedBy=? WHERE PolicyID=?')->execute([$days,$trigger,$method,$basis,$actor,$id]);logAudit($pdo,$actor,'Retention Policy Updated',"Privacy retention policy #$id updated to $days days and $method.");$_SESSION['success']='Retention policy updated.';
 }elseif($action==='scan'){$count=generatePrivacyRetentionCases($pdo);logAudit($pdo,$actor,'Retention Scan Completed',"$count new eligible retention case(s) created.");$_SESSION['success']="$count new eligible retention case(s) added for review.";
 }
 elseif($action==='resolve_request'){
  $id=(int)$_POST['request_id'];$status=$_POST['status']??'';$notes=trim($_POST['resolution_notes']??'');if(!in_array($status,['Under Review','Approved','Partially Approved','Denied','Completed'],true)||mb_strlen($notes)<10)throw new RuntimeException('A valid status and detailed resolution notes are required.');$q=$pdo->prepare('SELECT * FROM privacy_requests WHERE RequestID=? FOR UPDATE');$q->execute([$id]);$request=$q->fetch(PDO::FETCH_ASSOC);if(!$request)throw new RuntimeException('Privacy request not found.');$pdo->prepare('UPDATE privacy_requests SET Status=?,ResolutionNotes=?,ReviewedBy=?,ResolvedAt=IF(? IN (\'Approved\',\'Partially Approved\',\'Denied\',\'Completed\'),NOW(),NULL) WHERE RequestID=?')->execute([$status,$notes,$actor,$status,$id]);
  if(in_array($status,['Approved','Completed'],true)&&in_array($request['RequestType'],['Anonymization','Erasure or Blocking'],true)){$apps=$pdo->prepare("SELECT ApplicationID FROM application WHERE UserID=? AND Status IN('Withdrawn','Rejected','Disqualified')");$apps->execute([$request['UserID']]);$ins=$pdo->prepare("INSERT IGNORE INTO privacy_retention_cases(PolicyKey,RecordType,RecordID,SubjectUserID,RecordDescription,EligibleAt) VALUES('applications','Application',?,?,?,NOW())");foreach($apps->fetchAll(PDO::FETCH_COLUMN) as $app)$ins->execute([(string)$app,(int)$request['UserID'],"Approved privacy request #$id for application #$app"]);}
  if($request['RequestType']==='Consent Withdrawal'&&in_array($status,['Approved','Completed'],true))$pdo->prepare("UPDATE privacy_consents SET ConsentStatus='Withdrawn',WithdrawnAt=NOW() WHERE UserID=? AND ConsentStatus='Granted'")->execute([$request['UserID']]);logAudit($pdo,$actor,'Privacy Request Reviewed',"Privacy request #$id set to $status. Notes: $notes");$_SESSION['success']='Privacy request decision recorded.';
 }elseif($action==='case_hold'){$id=(int)$_POST['case_id'];$hold=(int)($_POST['legal_hold']??0);$reason=trim($_POST['reason']??'');if($hold&&mb_strlen($reason)<10)throw new RuntimeException('A legal-hold reason of at least 10 characters is required.');$pdo->prepare("UPDATE privacy_retention_cases SET LegalHold=?,LegalHoldReason=?,Status=IF(?=1,'Deferred',IF(Status='Deferred','Eligible',Status)) WHERE CaseID=?")->execute([$hold,$hold?$reason:null,$hold,$id]);logAudit($pdo,$actor,'Privacy Legal Hold Changed',"Retention case #$id legal hold=".($hold?'yes':'no').($reason?". Reason: $reason":''));$_SESSION['success']='Legal-hold status updated.';
 }elseif($action==='approve_case'){$id=(int)$_POST['case_id'];$reason=trim($_POST['reason']??'');if(mb_strlen($reason)<10)throw new RuntimeException('Approval reason must contain at least 10 characters.');$stmt=$pdo->prepare("UPDATE privacy_retention_cases SET Status='Approved',ApprovalReason=?,ApprovedBy=?,ApprovedAt=NOW() WHERE CaseID=? AND Status='Eligible' AND LegalHold=0");$stmt->execute([$reason,$actor,$id]);if(!$stmt->rowCount())throw new RuntimeException('Only an eligible case without a legal hold can be approved.');logAudit($pdo,$actor,'Privacy Disposal Approved',"Retention case #$id approved. Reason: $reason");$_SESSION['success']='Case approved. A separate execution step is still required.';
 }elseif($action==='execute_case'){$id=(int)$_POST['case_id'];$confirm=trim($_POST['confirmation']??'');if($confirm!=='DISPOSE')throw new RuntimeException('Type DISPOSE exactly to execute the approved disposition.');$pdo->beginTransaction();$evidence=executePrivacyRetentionCase($pdo,$id,$actor);logAudit($pdo,$actor,'Privacy Disposition Executed',"Retention case #$id completed. $evidence");$pdo->commit();$_SESSION['success']='Approved disposition completed and audited.';
 }else throw new RuntimeException('Invalid privacy lifecycle action.');
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}
header('Location: '.$adminBack);exit;
